-- Cheers · production database (Supabase/PostgreSQL)
create extension if not exists pgcrypto;

create table organizations (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, created_at timestamptz default now());
create table locations (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id) on delete cascade, name text not null, currency text not null default 'COP', created_at timestamptz default now());
create table profiles (id uuid primary key references auth.users(id) on delete cascade, organization_id uuid not null references organizations(id) on delete cascade, location_id uuid references locations(id), name text not null, role text not null check (role in ('admin','manager','cashier','bar','kitchen')), created_at timestamptz default now());
create table dining_tables (id uuid primary key default gen_random_uuid(), location_id uuid not null references locations(id) on delete cascade, name text not null, code text not null, active boolean default true, unique(location_id,code));
create table categories (id uuid primary key default gen_random_uuid(), location_id uuid not null references locations(id) on delete cascade, name text not null, sort_order integer default 0);
create table products (id uuid primary key default gen_random_uuid(), location_id uuid not null references locations(id) on delete cascade, category_id uuid references categories(id), name text not null, description text, price numeric(12,2) not null check(price >= 0), active boolean default true, image_url text, created_at timestamptz default now());
create table ingredients (id uuid primary key default gen_random_uuid(), location_id uuid not null references locations(id) on delete cascade, name text not null, unit text not null, stock numeric(12,3) not null default 0, minimum_stock numeric(12,3) not null default 0, cost numeric(12,2) default 0);
create table recipes (product_id uuid not null references products(id) on delete cascade, ingredient_id uuid not null references ingredients(id) on delete cascade, amount numeric(12,3) not null check(amount > 0), primary key(product_id,ingredient_id));
create table orders (id uuid primary key default gen_random_uuid(), location_id uuid not null references locations(id) on delete cascade, table_id uuid references dining_tables(id), code text not null, order_type text not null check(order_type in ('table','takeaway')), status text not null default 'new' check(status in ('new','preparing','ready','completed','cancelled')), notes text, total numeric(12,2) not null default 0, created_at timestamptz default now(), unique(location_id,code));
create table order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references orders(id) on delete cascade, product_id uuid references products(id), name text not null, quantity integer not null check(quantity > 0), unit_price numeric(12,2) not null);
create table payments (id uuid primary key default gen_random_uuid(), order_id uuid not null references orders(id) on delete cascade, amount numeric(12,2) not null, method text not null, created_at timestamptz default now());
create table inventory_movements (id uuid primary key default gen_random_uuid(), ingredient_id uuid not null references ingredients(id) on delete cascade, amount numeric(12,3) not null, reason text not null, order_id uuid references orders(id), created_at timestamptz default now());
create table table_requests (id uuid primary key default gen_random_uuid(), location_id uuid not null references locations(id) on delete cascade, table_id uuid references dining_tables(id), request_type text not null check(request_type in ('Cuenta','Agua','Mesero','Cubiertos')), note text, resolved_at timestamptz, resolved_by uuid references profiles(id), created_at timestamptz default now());
create table product_options (id uuid primary key default gen_random_uuid(), product_id uuid not null references products(id) on delete cascade, name text not null, active boolean default true, sort_order integer default 0);
create table customers (id uuid primary key default gen_random_uuid(), location_id uuid not null references locations(id) on delete cascade, name text not null, phone text default '', credit_limit numeric(12,2) not null default 0, notes text default '', active boolean not null default true, created_at timestamptz not null default now());
create table customer_ledger (id uuid primary key default gen_random_uuid(), customer_id uuid not null references customers(id) on delete cascade, order_id uuid references orders(id) on delete set null, kind text not null check (kind in ('charge','payment')), amount numeric(12,2) not null check (amount > 0), method text default '', note text default '', created_at timestamptz not null default now());
alter table locations add column if not exists address text default '', add column if not exists hours text default '', add column if not exists whatsapp text default '', add column if not exists instagram text default '';
alter table orders add column if not exists customer_name text default '';
alter table order_items add column if not exists selected_options jsonb default '[]'::jsonb, add column if not exists note text default '';
alter table orders add column if not exists customer_id uuid references customers(id) on delete set null;

alter table organizations enable row level security; alter table locations enable row level security; alter table profiles enable row level security; alter table dining_tables enable row level security; alter table categories enable row level security; alter table products enable row level security; alter table ingredients enable row level security; alter table recipes enable row level security; alter table orders enable row level security; alter table order_items enable row level security; alter table payments enable row level security; alter table inventory_movements enable row level security;
alter table table_requests enable row level security; alter table product_options enable row level security;
alter table customers enable row level security; alter table customer_ledger enable row level security;

create or replace function current_organization() returns uuid language sql stable security definer set search_path=public as $$ select organization_id from profiles where id = auth.uid() $$;
create policy "organization isolation" on locations for all using (organization_id=current_organization()) with check (organization_id=current_organization());
create policy "organization isolation" on profiles for all using (organization_id=current_organization()) with check (organization_id=current_organization());
create policy "organization isolation" on dining_tables for all using (location_id in (select id from locations where organization_id=current_organization())) with check (location_id in (select id from locations where organization_id=current_organization()));
create policy "organization isolation" on categories for all using (location_id in (select id from locations where organization_id=current_organization())) with check (location_id in (select id from locations where organization_id=current_organization()));
create policy "organization isolation" on products for all using (location_id in (select id from locations where organization_id=current_organization())) with check (location_id in (select id from locations where organization_id=current_organization()));
create policy "organization isolation" on ingredients for all using (location_id in (select id from locations where organization_id=current_organization())) with check (location_id in (select id from locations where organization_id=current_organization()));
create policy "organization isolation" on orders for all using (location_id in (select id from locations where organization_id=current_organization())) with check (location_id in (select id from locations where organization_id=current_organization()));
create policy "organization isolation" on order_items for all using (order_id in (select o.id from orders o join locations l on l.id=o.location_id where l.organization_id=current_organization())) with check (order_id in (select o.id from orders o join locations l on l.id=o.location_id where l.organization_id=current_organization()));
create policy "organization isolation" on payments for all using (order_id in (select o.id from orders o join locations l on l.id=o.location_id where l.organization_id=current_organization())) with check (order_id in (select o.id from orders o join locations l on l.id=o.location_id where l.organization_id=current_organization()));
create policy "organization isolation" on recipes for all using (product_id in (select p.id from products p join locations l on l.id=p.location_id where l.organization_id=current_organization())) with check (product_id in (select p.id from products p join locations l on l.id=p.location_id where l.organization_id=current_organization()));
create policy "organization isolation" on inventory_movements for all using (ingredient_id in (select i.id from ingredients i join locations l on l.id=i.location_id where l.organization_id=current_organization())) with check (ingredient_id in (select i.id from ingredients i join locations l on l.id=i.location_id where l.organization_id=current_organization()));
create policy "organization isolation" on table_requests for all using (location_id in (select id from locations where organization_id=current_organization())) with check (location_id in (select id from locations where organization_id=current_organization()));
create policy "organization isolation" on product_options for all using (product_id in (select p.id from products p join locations l on l.id=p.location_id where l.organization_id=current_organization())) with check (product_id in (select p.id from products p join locations l on l.id=p.location_id where l.organization_id=current_organization()));
